Amazon Aurora PostgreSQL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_aurora_postgresql, "Amazon Aurora PostgreSQL") {
    Component(Relational_Storage_Engine, "Relational Storage Engine", "PostgreSQL Database Engine", "Stores active case management data, transaction history, and fraud investigation records.")
}

Rel(Relational_Storage_Engine, Amazon_RDS_Proxy, "Accepts connection pools and queries", "PostgreSQL wire protocol over TLS 1.3")

@enduml

Amazon ElastiCache (Redis).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_elasticache_redis, "Amazon ElastiCache (Redis)") {
    Component(feature_store_engine_redis_oss, "Feature Store Engine (Redis OSS)", "Amazon ElastiCache (Redis) / cache.m6g", "In-memory key-value store holding pre-computed user/device velocity metrics.")
    Component(replication_manager, "Replication Manager", "Redis Cluster & Multi-AZ", "Handles asynchronous replication across Multi-AZ nodes for high availability.")
    Component(write_through_ingestion_handler, "Write-Through Ingestion Handler", "Redis Handler", "Manages asynchronous updates to feature states without blocking scoring.")
}

Rel(write_through_ingestion_handler, feature_store_engine_redis_oss, "Updates feature states", "Internal")
Rel(replication_manager, feature_store_engine_redis_oss, "Synchronizes data across Multi-AZ nodes", "Internal")

@enduml

Amazon SQS.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Ext(Real_Time_Scoring_Engine, "Real-Time Scoring Engine", "Go / Java, AWS ECS Fargate", "Sends asynchronous telemetry and audit events")
System_Ext(Case_Management_Backend, "Case Management Backend", "AWS ECS Fargate", "Consumes messages via Long Polling and DeleteMessage")

Container_Boundary(amazon_sqs, "Amazon SQS") {
    Component(Standard_Queue, "Standard Queue", "Amazon SQS Standard Queue", "Buffers asynchronous telemetry and audit events sent by the Real-Time Scoring Engine.")
    Component(Dead_Letter_Queue, "Dead-Letter Queue", "Amazon SQS DLQ", "Captures messages that fail processing for later analysis and error handling.")
}

Rel(Real_Time_Scoring_Engine, Standard_Queue, "Sends asynchronous telemetry and audit events", "AWS SDK/SQS API via Interface VPC Endpoint")
Rel(Standard_Queue, Case_Management_Backend, "Consumes messages via Long Polling and DeleteMessage", "AWS SDK/SQS API via Interface VPC Endpoint")
Rel(Standard_Queue, Dead_Letter_Queue, "Routes failed messages upon processing exhaustion", "Internal SQS Redrive")
@enduml
